package com.bank.deploy;

public class SignalReading {
    private final String name;
    private final double before;     // value just BEFORE deploy
    private final double after;      // value just AFTER deploy
    private final boolean deployControls;  // false = external (e.g. gateway)

    public SignalReading(String name, double before, double after, boolean deployControls) {
        this.name = name;
        this.before = before;
        this.after = after;
        this.deployControls = deployControls;
    }

    public String getName() { return name; }
    public double getBefore() { return before; }
    public double getAfter() { return after; }
    public boolean isDeployControls() { return deployControls; }

    // Percentage change from before to after.
    public double percentChange() {
        if (before == 0) return after == 0 ? 0 : 100;
        return (after - before) / before * 100.0;
    }
}
