package com.bank.deploy;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class RegressionAnalyzer {
    private static final Logger log = Logger.getLogger(RegressionAnalyzer.class.getName());
    private final double regressionThresholdPct;   // e.g. 50% worse = regression

    public RegressionAnalyzer(double regressionThresholdPct) {
        this.regressionThresholdPct = regressionThresholdPct;
    }

    public List<RegressionFinding> analyze(List<SignalReading> readings) {
        List<RegressionFinding> findings = new ArrayList<>();
        for (SignalReading r : readings) {
            double pct = r.percentChange();
            boolean regressed = pct >= regressionThresholdPct;
            findings.add(new RegressionFinding(r.getName(), pct, regressed, r.isDeployControls()));
            if (regressed) {
                log.warning(() -> String.format("  REGRESSED %-22s %.0f%% worse (%s)",
                    r.getName(), pct, r.isDeployControls() ? "deploy-controlled" : "EXTERNAL"));
            } else {
                log.fine(() -> String.format("  ok        %-22s %.0f%% change", r.getName(), pct));
            }
        }
        return findings;
    }

    // Deploy is the cause only if a DEPLOY-CONTROLLED signal regressed.
    public boolean deployIsCause(List<RegressionFinding> findings) {
        return findings.stream().anyMatch(f -> f.isRegressed() && f.isDeployControlled());
    }
}
