package com.bank.deploy;

import java.util.List;
import java.util.logging.Logger;

public class RollbackAdvisor {
    private static final Logger log = Logger.getLogger(RollbackAdvisor.class.getName());

    public String advise(List<RegressionFinding> findings, boolean deployIsCause) {
        if (!deployIsCause) {
            return "Do NOT roll back — regression is in an EXTERNAL dependency. "
                 + "Engage the dependency owner / enable circuit breaker + fallback.";
        }
        boolean configOnly = findings.stream()
            .filter(RegressionFinding::isRegressed)
            .allMatch(f -> f.getSignal().contains("config") || f.getSignal().contains("flag"));
        if (configOnly) {
            String action = "Flip the feature flag OFF / revert the config — fastest safe restore, "
                          + "no full rollback needed.";
            log.info(() -> "  RESTORE: " + action);
            return action;
        }
        String action = "Roll back to last known-good version: blue-green flip to stable OR "
                      + "kubectl rollout undo. Verify p99 returns to baseline. Re-release via canary.";
        log.info(() -> "  RESTORE: " + action);
        return action;
    }
}
