package com.bank.deploy;

import java.util.List;
import java.util.logging.*;

public class DeployLatencyDemo {
    private static final Logger log = Logger.getLogger(DeployLatencyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // v5.0 deploy of transfer-service. BEFORE vs AFTER readings at the deploy boundary.
        List<SignalReading> readings = List.of(
            new SignalReading("p99 latency (ms)", 120, 650, true),
            new SignalReading("error rate (%)", 0.2, 0.3, true),
            new SignalReading("account-lookup query (ms)", 10, 410, true),  // lost index!
            new SignalReading("CPU (%)", 45, 52, true),
            new SignalReading("GC pause (ms/min)", 80, 520, true),          // allocation spike
            new SignalReading("payment-gateway (ms)", 90, 95, false),       // external, fine
            new SignalReading("config:threadpool", 50, 50, true));          // unchanged

        log.warning("Deploy v5.0 at 02:10:00 — comparing BEFORE vs AFTER for transfer-service");
        RegressionAnalyzer analyzer = new RegressionAnalyzer(50.0);
        List<RegressionFinding> findings = analyzer.analyze(readings);
        boolean cause = analyzer.deployIsCause(findings);
        log.info(() -> "Deploy confirmed as cause? " + cause);

        String restore = new RollbackAdvisor().advise(findings, cause);
        log.info(() -> "FINAL ACTION: " + restore);
    }
}
